  const demo=p.visual==='manga'?'<div class="case-copy demo-case-copy"><h2>Enter the reading room.</h2><div id="manga-demo"></div></div>'
    :p.visual==='archive'?'<div class="case-copy demo-case-copy"><h2>Try the archive.</h2><div id="archive-demo"></div></div>'
    :p.visual==='booking'?'<div class="case-copy demo-case-copy"><h2>Try the booking flow.</h2><div id="booking-demo"></div></div>'
    :p.visual==='commerce'?'<div class="case-copy demo-case-copy"><h2>Try the storefront.</h2><div id="commerce-demo"></div></div>'
    :p.visual==='operations'?'<div class="case-copy demo-case-copy"><h2>Try the decision workbench.</h2><div class="workspace" id="workspace"></div></div>'
    :p.visual==='researchtools'?'<div class="case-copy demo-case-copy"><h2>Try the research toolkit.</h2><div id="research-tools-case"></div></div>'
    :['fieldcompanion','dataprep','documents','commerceops','qualityroom','scopebuilder'].includes(p.visual)?`<div class="case-copy demo-case-copy"><h2>Open the working demonstration.</h2><div id="next-wave-demo" data-demo="${esc(p.visual)}"></div></div>`
    :['morphslides','logostudio','wedding'].includes(p.visual)?`<div class="case-copy creative-case"><h2>Try the ${p.visual==='wedding'?'invitation':'studio'}.</h2><div id="creative-demo" data-demo="${esc(p.visual)}"></div></div>`:'';
  $('#main').innerHTML=`<article class="case-page entrance"><a href="${homeHref('field')}" class="back">← BACK TO THE FIELD</a><span class="eyebrow">${esc(p.status)} / ${esc(p.category)}</span><h1>${esc(p.title)}</h1><p class="case-summary">${esc(p.summary)}</p><div class="case-links">${safeUrl(p.repositoryUrl)?`<a class="text-link" href="${esc(p.repositoryUrl)}" target="_blank" rel="noopener">Source repository ↗</a>`:''}${safeUrl(p.liveUrl)?`<a class="text-link" href="${esc(p.liveUrl)}" target="_blank" rel="noopener">Visit original site ↗</a>`:''}<button id="focus-toggle">Focus reading</button><button id="share-project">Copy project link</button></div><div class="case-visual">${visual(p)}<span class="illustration">${p.mediaId||p.coverUrl?'AUTHENTIC PROJECT MEDIA':'ORIGINAL SYSTEM ILLUSTRATION — NOT A SCREENSHOT'}</span></div>${projectProof(p)}<div class="tags">${p.technologies.map(t=>`<span>${esc(t)}</span>`).join('')}</div>${caseNarrative(p).map(([title,key])=>`<div class="case-copy"><h2>${title}</h2><p>${esc(p[key])}</p></div>`).join('')}<div class="case-copy"><h2>Evidence trail.</h2><div class="evidence-list">${p.evidence.map(item=>safeUrl(p.repositoryUrl)?`<a href="${esc(p.repositoryUrl)}/blob/${esc(p.revision||'main')}/${item.split('/').map(encodeURIComponent).join('/')}" target="_blank" rel="noopener">${esc(item)} ↗</a>`:`<span>${esc(item)}</span>`).join('')}<p>${safeUrl(p.repositoryUrl)?'Claims describe inspected source files and public project behavior. Private records, confidential workflows, and unmeasured performance are not inferred.':'This is an interactive concept built inside the portfolio. It is clearly separated from verified client or production work.'}</p></div></div>${demo}<a class="text-link" href="${homeHref('field')}">Continue exploring ↗</a></article>`;
  $('#focus-toggle').onclick=()=>{document.body.classList.toggle('focus-reading');$('#focus-toggle').textContent=document.body.classList.contains('focus-reading')?'Exit focus reading':'Focus reading'};
  $('#share-project').onclick=()=>{const url=projectShareUrl(p.slug);navigator.clipboard?.writeText(url).then(()=>toast('Project link copied.')).catch(()=>toast(url))};
  if($('#manga-demo'))mangaDemo();
