async function resume(){document.body.classList.remove('focus-reading');const documentPanel=data.resume?`<div class="resume-document"><div><span class="eyebrow">PUBLISHED DOCUMENT</span><p>Latest approved PDF · ${esc(data.resume.uploadedAt.slice(0,10))}</p></div><div class="case-links"><button class="solid-button" id="resume-preview">View PDF</button><button id="resume-download">Download PDF ↓</button></div></div><div id="resume-viewer"></div>`:`<div class="resume-empty"><h3>${data.contentSource==='snapshot'?'The CV service is temporarily unavailable.':'The PDF is being prepared.'}</h3><p>${data.contentSource==='snapshot'?'I could not check the latest published PDF. Please try again shortly.':'No approved PDF is currently published.'} The professional summary and verified project links remain available.</p><a class="text-link" href="${homeHref('field')}">Explore the work ↗</a></div>`;$('#main').innerHTML=`<article class="resume-page"><a class="back" href="${homeHref('profile')}">← BACK TO PROFILE</a><span class="eyebrow">09 / RESUME</span><h1>Experience, capabilities,<br>and current work.</h1><p class="resume-lead">Full-stack developer working across web systems, operational data, workflow automation, and interface design in Balikpapan, Indonesia.</p><div class="resume-overview"><section><span class="eyebrow">CURRENT ROLE</span><h2>PT. Wulandari Bangun Laksana</h2><p>February 2026 — Present</p><small>Previously completed an IT Support internship at the same company.</small></section><section><span class="eyebrow">EDUCATION</span><h2>Bachelor’s Degree</h2><p>Informatics Engineering · GPA 3.84 / 4.00</p></section><section><span class="eyebrow">CORE CAPABILITIES</span><p>Full-stack web development · Google Apps Script · Excel and Google Sheets · data reconciliation · workflow automation · UI/UX · cloud and API integration</p></section><section><span class="eyebrow">SELECTED PROOF</span><div class="resume-proof-links">${data.projects.filter(p=>p.status==='Real Project').slice(0,4).map(p=>`<a href="${projectHref(p.slug)}">${esc(p.name)} ↗</a>`).join('')}</div></section></div>${documentPanel}</article>`;if(data.resume){$('#resume-preview').onclick=()=>action($('#resume-preview'),async()=>{const f=await rpc('getResumeFile');const url=fileUrl(f);$('#resume-viewer').innerHTML=`<iframe class="resume-frame" title="Kevin Simatupang resume preview" src="${url}"></iframe><p class="admin-help">If the embedded preview is unavailable on mobile, use Download PDF.</p>`});$('#resume-download').onclick=()=>action($('#resume-download'),async()=>downloadFile(await rpc('getResumeFile')));}}
const objectUrls=[];function fileUrl(f){const bytes=Uint8Array.from(atob(f.base64),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:f.mime}));objectUrls.push(url);return url;}function downloadFile(f){const a=document.createElement('a');a.href=fileUrl(f);a.download=f.name;a.click();}function clearUrls(){objectUrls.splice(0).forEach(u=>URL.revokeObjectURL(u));}
function renderSearch(){const q=$('#search-input').value.toLowerCase();const commands=[['Explore the work',homeHref('field')],['Open the Data Lab',homeHref('lab')],['Research support and SPSS',homeHref('research'),'statistics thesis questionnaire regression writing methodology'],['Start a research consultation',homeHref('research-intake'),'brief thesis support'],['View services',homeHref('services'),'research data excel website'],['View resume',homeHref('resume')],['Profile',homeHref('profile')],['Contact Kevin',homeHref('connect')],...data.projects.map(p=>[p.name,projectHref(p.slug),p.technologies.join(' ')])];$('#search-results').innerHTML=commands.filter(c=>c.join(' ').toLowerCase().includes(q)).map(c=>`<a href="${esc(c[1])}">${esc(c[0])} ↗</a>`).join('')||'<p>No matching spaces. Try “data”, “SPSS”, “writing”, or “Galilea”.</p>';$$('#search-results a').forEach(a=>a.onclick=()=>$('#search-dialog').close());}
$('#search-open').onclick=()=>{$('#search-dialog').showModal();renderSearch();$('#search-input').focus()};$('#search-input').oninput=renderSearch;$$('[data-close]').forEach(b=>b.onclick=()=>b.closest('dialog').close());$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d)d.close()}));document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#search-dialog').open)$('#search-dialog').close();else $('#search-open').click();}});
