let current='';function route(){if(typeof disposeManga==='function')disposeManga();clearUrls();const hash=decodeURIComponent(location.hash.slice(1)||'home');if(data.admin){admin();return;}if(hash.startsWith('project/')){current='project';casePage(hash.slice(8));window.scrollTo(0,0)}else if(hash==='resume'){current='resume';resume();window.scrollTo(0,0)}else{if(current!=='home'){home();current='home';}requestAnimationFrame(()=>document.getElementById(hash)?.scrollIntoView({behavior:'instant'}));}document.title=hash.startsWith('project/')?(data.projects.find(p=>p.slug===hash.slice(8))?.name||'Exhibit')+' — Kevin Simatupang':'Kevin Simatupang — The Living Index';requestAnimationFrame(initImmersion);}
